  @Test
  void posesAreFiniteAtEverySignalLimit() {
    for (RobotModel.Signal s : RobotModel.Signal.values()) {
      for (double value : new double[] {s.min, s.max}) {
        double[] signals = RobotModel.zeroSignals();
        signals[s.ordinal()] = value;
        for (Pose3d p : RobotModel.componentPoses(signals)) {
          assertTrue(Double.isFinite(p.getX()) && Double.isFinite(p.getY()) && Double.isFinite(p.getZ()), s + " at " + value);
          assertTrue(Double.isFinite(p.getRotation().getQuaternion().getW()), s + " at " + value);
        }
      }
    }
  }
